func TestAutonomiaBatchSnapshotMemoizaProyectoOperacion(t *testing.T) {
	prev := autonomiaGetProyectoOperacionFn
	t.Cleanup(func() { autonomiaGetProyectoOperacionFn = prev })

	calls := 0
	autonomiaGetProyectoOperacionFn = func(proyectoID int64) (*db.ProyectoOperacion, error) {
		calls++
		return &db.ProyectoOperacion{ProyectoID: proyectoID, EstadoOperativo: db.ProyectoOperativoActivo}, nil
	}

	snapshot := &autonomiaBatchSnapshot{
		projectOperationByID:   map[int64]*db.ProyectoOperacion{},
		projectOperationLoaded: map[int64]struct{}{},
	}

	for i := 0; i < 2; i++ {
		op, err := snapshot.projectOperation(91)
		if err != nil {
			t.Fatalf("projectOperation: %v", err)
		}
		if op == nil || op.ProyectoID != 91 {
			t.Fatalf("projectOperation inesperada: %+v", op)
		}
	}
	if calls != 1 {
		t.Fatalf("deberia memoizar GetProyectoOperacion, calls=%d", calls)
	}
}

func TestAutonomiaBatchSnapshotMemoizaProyectoDisponibleParaAutonomia(t *testing.T) {
	prev := autonomiaProyectoDisponibleParaAutonomiaFn
	t.Cleanup(func() { autonomiaProyectoDisponibleParaAutonomiaFn = prev })

	calls := 0
	autonomiaProyectoDisponibleParaAutonomiaFn = func(proyectoID int64) (bool, error) {
		calls++
		return proyectoID == 92, nil
	}

	snapshot := &autonomiaBatchSnapshot{
		projectAvailableByID:   map[int64]bool{},
		projectAvailableLoaded: map[int64]struct{}{},
	}

	for i := 0; i < 2; i++ {
		disponible, err := snapshot.projectAvailableForAutonomy(92)
		if err != nil {
			t.Fatalf("projectAvailableForAutonomy: %v", err)
		}
		if !disponible {
			t.Fatalf("deberia devolver disponible=true")
		}
	}
	if calls != 1 {
		t.Fatalf("deberia memoizar ProyectoDisponibleParaAutonomia, calls=%d", calls)
	}
}

func TestAutonomiaBatchSnapshotMemoizaProyectoAutocierre(t *testing.T) {
	prev := autonomiaProyectoTerminadoFn
	t.Cleanup(func() { autonomiaProyectoTerminadoFn = prev })

	calls := 0
	autonomiaProyectoTerminadoFn = func(proyecto *db.Proyecto) (bool, string, error) {
		calls++
		return true, "sin trabajo pendiente", nil
	}

	snapshot := &autonomiaBatchSnapshot{
		projectAutoCloseByID:   map[int64]autonomiaProjectAutoCloseStatus{},
		projectAutoCloseLoaded: map[int64]struct{}{},
	}
	proyecto := &db.Proyecto{ID: 93, Slug: "memo-autoclose"}

	for i := 0; i < 2; i++ {
		terminado, motivo, err := snapshot.projectAutoCloseStatus(proyecto)
		if err != nil {
			t.Fatalf("projectAutoCloseStatus: %v", err)
		}
		if !terminado || motivo != "sin trabajo pendiente" {
			t.Fatalf("estado autocierre inesperado: terminado=%v motivo=%q", terminado, motivo)
		}
	}
	if calls != 1 {
		t.Fatalf("deberia memoizar proyectoTerminadoAutonomamente, calls=%d", calls)
	}
}

func TestAutonomiaRuntimeRecoveryShouldAttemptThrottleaSesionesActivas(t *testing.T) {
	resetAutonomiaRuntimeRecoveryGate()
	t.Cleanup(resetAutonomiaRuntimeRecoveryGate)

	if !autonomiaRuntimeRecoveryShouldAttempt("Codex1", 3, "activa") {
		t.Fatalf("el primer intento activo debe permitirse")
	}
	if autonomiaRuntimeRecoveryShouldAttempt("Codex1", 3, "activa") {
		t.Fatalf("el segundo intento activo inmediato debe quedar throttled")
	}
}

func TestAutonomiaRuntimeRecoveryShouldAttemptNoThrottleaSesionesPausadas(t *testing.T) {
	resetAutonomiaRuntimeRecoveryGate()
	t.Cleanup(resetAutonomiaRuntimeRecoveryGate)

	if !autonomiaRuntimeRecoveryShouldAttempt("Codex1", 3, "pausada") {
		t.Fatalf("la sesion pausada debe permitirse siempre")
	}
	if !autonomiaRuntimeRecoveryShouldAttempt("Codex1", 3, "pausada") {
		t.Fatalf("la sesion pausada no debe quedar throttled")
	}
}

