func TestBuildRuntimeMailboxBatchBucketsAgrupaPorKind(t *testing.T) {
	proyectoID := int64(11)
	buckets := buildRuntimeMailboxBatchBuckets([]*db.RuntimeMailboxMessage{
		{ID: 1, ToAgente: "Codex1", ProyectoID: &proyectoID, Kind: "pipeline_local"},
		{ID: 2, ToAgente: "Codex1", ProyectoID: &proyectoID, Kind: "instruction"},
		{ID: 3, ToAgente: "Codex1", ProyectoID: &proyectoID, Kind: db.MailboxKindGovernanceRefresh},
		{ID: 4, ToAgente: "Codex1", ProyectoID: &proyectoID, Kind: "watchdog"},
		{ID: 5, ToAgente: "Codex1", ProyectoID: &proyectoID, Kind: "autonomia"},
	})
	if len(buckets.all) != 5 {
		t.Fatalf("all inesperado: %d", len(buckets.all))
	}
	if len(buckets.pipeline) != 1 || buckets.pipeline[0].ID != 1 {
		t.Fatalf("pipeline inesperado: %+v", buckets.pipeline)
	}
	if len(buckets.instruction) != 1 || buckets.instruction[0].ID != 2 {
		t.Fatalf("instruction inesperado: %+v", buckets.instruction)
	}
	if len(buckets.refresh) != 1 || buckets.refresh[0].ID != 3 {
		t.Fatalf("refresh inesperado: %+v", buckets.refresh)
	}
	if len(buckets.watchdog) != 1 || buckets.watchdog[0].ID != 4 {
		t.Fatalf("watchdog inesperado: %+v", buckets.watchdog)
	}
}

func TestProcesarRuntimeMailboxInteractivoMensajeOmiteSupervisionParaHandleNoInteractivo(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)
	resetRuntimeMailboxReevaluationGate()
	t.Cleanup(resetRuntimeMailboxReevaluationGate)

	prevSync := runtimeMailboxSyncSupervisedHandleFn
	t.Cleanup(func() { runtimeMailboxSyncSupervisedHandleFn = prevSync })
	prevBuild := runtimeMailboxBuildInteractiveInstructionFn
	t.Cleanup(func() { runtimeMailboxBuildInteractiveInstructionFn = prevBuild })

	if err := db.RegistrarAgente("Codex1", "programador"); err != nil {
		t.Fatalf("registrar agente: %v", err)
	}
	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador",
		Nombre:  "Orquestador",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}

	msgID, err := db.EnviarRuntimeMailbox(&db.RuntimeMailboxMessage{
		FromAgente:  "server",
		ToAgente:    "Codex1",
		ProyectoID:  &proyectoID,
		Kind:        "instruction",
		PayloadJSON: `{"texto":"instruccion interactiva"}`,
	})
	if err != nil {
		t.Fatalf("mailbox: %v", err)
	}
	msg, err := db.GetRuntimeMailbox(msgID)
	if err != nil || msg == nil {
		t.Fatalf("get mailbox: msg=%+v err=%v", msg, err)
	}

	handle := &db.RuntimeHandle{
		ID:               42,
		Agente:           "Codex1",
		ProyectoID:       &proyectoID,
		Estado:           "activo",
		Transporte:       "tmux",
		HandleKind:       "session",
		MetadataJSON:     `{"driver":"tmux_cli_session","tmux_session":"orq-codex1","tmux_pane_id":"%9","can_send_input":false,"mailbox_delivery_mode":"session_resume"}`,
		CapabilitiesJSON: `{"can_send_input":false,"mailbox_delivery_mode":"session_resume"}`,
	}
	snapshot := &runtimeMailboxBatchSnapshot{
		activeHandles: map[string]*db.RuntimeHandle{
			runtimeMailboxBatchKey("Codex1", &proyectoID): handle,
		},
		activeHandleLoaded: map[string]struct{}{
			runtimeMailboxBatchKey("Codex1", &proyectoID): {},
		},
		ordersByAgentProject: map[string][]*db.RuntimeOrder{},
		ordersLoaded: map[string]struct{}{
			runtimeMailboxBatchKey("Codex1", &proyectoID): {},
		},
		supervisedByHandleID: map[int64]runtimeMailboxSupervisedHandleSnapshot{},
	}

	supervisedCalls := 0
	buildCalls := 0
	runtimeMailboxSyncSupervisedHandleFn = func(handle *db.RuntimeHandle, runtime *db.RuntimeInstance, source string) (*db.RuntimeHandle, *db.RuntimeInstance, string, error) {
		supervisedCalls++
		return handle, runtime, "", nil
	}
	runtimeMailboxBuildInteractiveInstructionFn = func(msg *db.RuntimeMailboxMessage) (string, bool) {
		buildCalls++
		return "instruccion interactiva", true
	}

	dispatched, err := procesarRuntimeMailboxInteractivoMensaje(msg, map[int64]struct{}{}, snapshot)
	if err != nil {
		t.Fatalf("procesarRuntimeMailboxInteractivoMensaje: %v", err)
	}
	if dispatched {
		t.Fatal("no deberia despachar por interactive cuando el handle es session_resume")
	}
	if supervisedCalls != 0 {
		t.Fatalf("no deberia supervisar handles no interactivos, calls=%d", supervisedCalls)
	}
	if buildCalls != 0 {
		t.Fatalf("no deberia construir el texto para handles no interactivos, calls=%d", buildCalls)
	}
}

