func TestEncolarContinuacionTareaReasignadaSiCorrespondeEscalaFollowupBloqueadoAlSupervisor(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)

	if err := db.RegistrarAgente("Codex1", "programador"); err != nil {
		t.Fatalf("registrar agente worker: %v", err)
	}
	if err := db.RegistrarAgente("CodexSupervisor", "admin"); err != nil {
		t.Fatalf("registrar supervisor: %v", err)
	}
	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador",
		Nombre:  "Orquestador",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	if _, err := db.UpsertProyectoAutonomia(&db.ProyectoAutonomia{
		ProyectoID:           proyectoID,
		Enabled:              true,
		ObjetivoGeneral:      "Terminar la app",
		DefinitionOfDoneJSON: `{"done":true}`,
		SupervisorAgente:     "CodexSupervisor",
		EstadoAutonomia:      db.AutonomiaProyectoActiva,
	}); err != nil {
		t.Fatalf("upsert proyecto autonomia: %v", err)
	}
	if err := db.ActivarAsignacion("CodexSupervisor", proyectoID, "supervision"); err != nil {
		t.Fatalf("activar asignacion supervisor: %v", err)
	}
	tareaID, err := db.CrearTarea(&db.Tarea{
		Titulo:     "Frente reactivado bloqueado",
		ProyectoID: &proyectoID,
		Prioridad:  db.PrioridadAlta,
		CreadoPor:  "tester",
	})
	if err != nil {
		t.Fatalf("crear tarea: %v", err)
	}
	if err := db.TomarTarea(tareaID, "Codex1"); err != nil {
		t.Fatalf("tomar tarea: %v", err)
	}
	if err := db.IniciarTarea(tareaID, "Codex1"); err != nil {
		t.Fatalf("iniciar tarea: %v", err)
	}
	verificationKey := verificationKeyContinuacionTareaReasignada("Codex1", tareaID, "reassign", "Gemma1")
	if _, err := db.EncolarRuntimeOrder(&db.RuntimeOrder{
		Agente:        "Codex1",
		ProyectoID:    &proyectoID,
		Tipo:          "nudge",
		Estado:        "fallida",
		PayloadJSON:   fmt.Sprintf(`{"kind":"autonomia","accion":"continuar_trabajo","verification_key":"%s","remediation_kind":"reassign"}`, verificationKey),
		ResultadoJSON: fmt.Sprintf(`{"dispatch_state":"failed","delivery_state":"blocked","verification_key":"%s","remediation_kind":"reassign","blocked_reason":"agent still blocked"}`, verificationKey),
	}); err != nil {
		t.Fatalf("crear follow-up bloqueado: %v", err)
	}

	if err := encolarContinuacionTareaReasignadaSiCorresponde("Codex1", &proyectoID, tareaID, "Gemma1", "worker_degradado", "continúa", nil); err != nil {
		t.Fatalf("encolar continuacion condicionada: %v", err)
	}

	orders, err := db.ListarRuntimeOrders(db.FiltroRuntimeOrders{ProyectoID: &proyectoID, Limit: 20})
	if err != nil {
		t.Fatalf("listar runtime orders: %v", err)
	}
	var supervisorNudge *db.RuntimeOrder
	var workerPending *db.RuntimeOrder
	for _, order := range orders {
		if order == nil {
			continue
		}
		switch {
		case order.Agente == "CodexSupervisor" && order.Tipo == "nudge":
			supervisorNudge = order
		case order.Agente == "Codex1" && order.Tipo == "nudge" && order.Estado == "pendiente" && strings.Contains(order.PayloadJSON, `"accion":"continuar_trabajo"`):
			workerPending = order
		}
	}
	if workerPending != nil {
		t.Fatalf("no deberia reencolar follow-up al mismo agente si ya quedó bloqueado: %+v", workerPending)
	}
	if supervisorNudge == nil || !strings.Contains(supervisorNudge.PayloadJSON, `"accion":"resolver_post_remediation_blocked"`) {
		t.Fatalf("deberia escalar al supervisor, got=%+v", supervisorNudge)
	}
	if !strings.Contains(supervisorNudge.PayloadJSON, `"verification_key":"`+verificationKey+`"`) {
		t.Fatalf("nudge al supervisor sin verification_key: %s", supervisorNudge.PayloadJSON)
	}
	tarea, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea: %v", err)
	}
	if tarea == nil || tarea.Estado != db.TareaBloqueada || !strings.Contains(strings.ToLower(tarea.Notas), "post-remediation bloqueado") {
		t.Fatalf("la tarea deberia anotar el bloqueo post-remediation: %+v", tarea)
	}
	bloqueos, err := db.ListarResumenBloqueos()
	if err != nil {
		t.Fatalf("listar bloqueos: %v", err)
	}
	var motivoBloqueo string
	for _, bloqueo := range bloqueos {
		if bloqueo.ID == tareaID {
			motivoBloqueo = strings.TrimSpace(bloqueo.Motivo)
			break
		}
	}
	if motivoBloqueo == "" || !esBloqueoAutonomiaAgenteRecuperable("Codex1", "Codex1", motivoBloqueo) {
		t.Fatalf("el bloqueo deberia ser compatible con recuperacion automatica, motivo=%q", motivoBloqueo)
	}
	tareas, err := db.ListarTareas(db.FiltroTareas{ProyectoID: &proyectoID})
	if err != nil {
		t.Fatalf("listar tareas: %v", err)
	}
	var blockedFollowupTask *db.Tarea
	for _, item := range tareas {
		if item != nil && item.Titulo == autonomiaPostRemediationBlockedTaskTitle {
			blockedFollowupTask = item
			break
		}
	}
	if blockedFollowupTask == nil {
		t.Fatalf("deberia crear tarea explicita de post-remediation bloqueado: %+v", tareas)
	}
	if blockedFollowupTask.Agente == nil || *blockedFollowupTask.Agente != "CodexSupervisor" {
		t.Fatalf("la tarea de post-remediation bloqueado deberia quedar en el supervisor: %+v", blockedFollowupTask)
	}
	if !strings.Contains(blockedFollowupTask.Notas, "verification_key:"+verificationKey) {
		t.Fatalf("la tarea de post-remediation bloqueado deberia conservar verification_key: %+v", blockedFollowupTask)
	}
	kind := "post_remediation_blocked_escalated"
	events, err := db.ListarAutonomyEvents(db.FiltroAutonomyEvents{TaskID: &tareaID, Kind: &kind, Limite: 10})
	if err != nil {
		t.Fatalf("ListarAutonomyEvents: %v", err)
	}
	if len(events) != 1 {
		t.Fatalf("esperaba 1 post_remediation_blocked_escalated, got=%d %+v", len(events), events)
	}
	if ev := events[0]; ev == nil || ev.Source != "control_plane" || fmt.Sprint(ev.StateDelta["agente"]) != "Codex1" || fmt.Sprint(ev.StateDelta["supervisor"]) != "CodexSupervisor" || fmt.Sprint(ev.StateDelta["verification_key"]) != verificationKey {
		t.Fatalf("post_remediation_blocked_escalated inesperado: %+v", ev)
	}

	if err := encolarContinuacionTareaReasignadaSiCorresponde("Codex1", &proyectoID, tareaID, "Gemma1", "worker_degradado", "continúa", nil); err != nil {
		t.Fatalf("segunda continuacion condicionada: %v", err)
	}
	tareas, err = db.ListarTareas(db.FiltroTareas{ProyectoID: &proyectoID})
	if err != nil {
		t.Fatalf("listar tareas segunda vez: %v", err)
	}
	countBlockedFollowup := 0
	for _, item := range tareas {
		if item != nil && item.Titulo == autonomiaPostRemediationBlockedTaskTitle {
			countBlockedFollowup++
		}
	}
	if countBlockedFollowup != 1 {
		t.Fatalf("no deberia duplicar tarea de post-remediation bloqueado, count=%d tareas=%+v", countBlockedFollowup, tareas)
	}
	orders, err = db.ListarRuntimeOrders(db.FiltroRuntimeOrders{ProyectoID: &proyectoID, Limit: 20})
	if err != nil {
		t.Fatalf("listar runtime orders tras segundo intento: %v", err)
	}
	countSupervisorNudges := 0
	for _, order := range orders {
		if order != nil && order.Agente == "CodexSupervisor" && order.Tipo == "nudge" && strings.Contains(order.PayloadJSON, `"accion":"resolver_post_remediation_blocked"`) {
			countSupervisorNudges++
		}
	}
	if countSupervisorNudges != 1 {
		t.Fatalf("no deberia duplicar nudge al supervisor si ya existe tarea post-remediation, count=%d orders=%+v", countSupervisorNudges, orders)
	}
	events, err = db.ListarAutonomyEvents(db.FiltroAutonomyEvents{TaskID: &tareaID, Kind: &kind, Limite: 10})
	if err != nil {
		t.Fatalf("ListarAutonomyEvents segunda vez: %v", err)
	}
	if len(events) != 1 {
		t.Fatalf("no deberia duplicar post_remediation_blocked_escalated, got=%d %+v", len(events), events)
	}
}

