func TestAsegurarTareaReplanAutonomiaSignalCreaFrenteParaSupervisor(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)

	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador",
		Nombre:  "Orquestador",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	policy := &supervisionapp.Policy{
		ProyectoID:           proyectoID,
		Enabled:              true,
		ObjetivoGeneral:      "Terminar la app sin intervención humana",
		DefinitionOfDoneJSON: `{"tests":"green"}`,
		SupervisorAgente:     "CodexSupervisor",
	}
	proyecto, err := db.GetProyecto(strconv.FormatInt(proyectoID, 10))
	if err != nil {
		t.Fatalf("get proyecto: %v", err)
	}
	supervisor := &db.Agente{Nombre: "CodexSupervisor", Rol: "admin"}
	item := &db.RuntimeTranscriptEntry{
		ID:             77,
		ProyectoID:     &proyectoID,
		Agente:         "CodexWorker",
		Classification: "needs_replan",
		Text:           "No tengo claro el siguiente paso útil",
	}

	note, err := asegurarTareasSignalTranscript(item, policy, proyecto, supervisor)
	if err != nil {
		t.Fatalf("asegurarTareasSignalTranscript: %v", err)
	}
	if !strings.HasPrefix(note, "replan_task_created:") {
		t.Fatalf("nota inesperada: %s", note)
	}
	tareas, err := db.ListarTareas(db.FiltroTareas{ProyectoID: &proyectoID})
	if err != nil {
		t.Fatalf("listar tareas: %v", err)
	}
	if len(tareas) != 1 {
		t.Fatalf("debería crear exactamente una tarea de replan, tareas=%+v", tareas)
	}
	if tareas[0].Titulo != autonomiaReplanTaskTitle {
		t.Fatalf("título de replan inesperado: %+v", tareas[0])
	}
	if tareas[0].Estado != db.TareaEnProgreso {
		t.Fatalf("la tarea de replan debería arrancarse para el supervisor, tarea=%+v", tareas[0])
	}
	if tareas[0].Agente == nil || *tareas[0].Agente != "CodexSupervisor" {
		t.Fatalf("la tarea de replan debería quedar en el supervisor, tarea=%+v", tareas[0])
	}
}

func TestIntentarReasignacionAutomaticaBlockedSignalTranscriptConRowsReasignaYNudgeaRelevo(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)

	if err := db.RegistrarAgente("Codex1", "programador"); err != nil {
		t.Fatalf("registrar agente origen: %v", err)
	}
	if err := db.RegistrarAgente("Codex2", "programador"); err != nil {
		t.Fatalf("registrar agente relevo: %v", err)
	}
	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador",
		Nombre:  "Orquestador",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	proyecto, err := db.GetProyecto(strconv.FormatInt(proyectoID, 10))
	if err != nil {
		t.Fatalf("get proyecto: %v", err)
	}
	tareaID, err := db.CrearTarea(&db.Tarea{
		Titulo:     "Frente bloqueado",
		ProyectoID: &proyectoID,
		Prioridad:  db.PrioridadAlta,
		CreadoPor:  "tester",
	})
	if err != nil {
		t.Fatalf("crear tarea: %v", err)
	}
	if err := db.TomarTarea(tareaID, "Codex1"); err != nil {
		t.Fatalf("tomar tarea: %v", err)
	}
	tarea, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea inicial: %v", err)
	}
	item := &db.RuntimeTranscriptEntry{
		ID:             91,
		ProyectoID:     &proyectoID,
		Agente:         "Codex1",
		Classification: "blocked",
		Text:           "blocked on missing project context",
	}
	rows := []agentesapp.Row{
		{
			Agente:          &db.Agente{Nombre: "Codex2", Rol: "programador"},
			Asignacion:      &db.Asignacion{Agente: "Codex2", ProyectoID: proyectoID, ProyectoSlug: "orquestador", Estado: db.AsignacionActiva},
			EstadoOperativo: "disponible",
			OpenTasks:       0,
		},
	}

	note, reassigned, err := intentarReasignacionAutomaticaBlockedSignalTranscriptConRows(item, proyecto, tarea, rows, openTasksProjectedFromRows(rows))
	if err != nil {
		t.Fatalf("intentarReasignacionAutomaticaBlockedSignalTranscriptConRows: %v", err)
	}
	if !reassigned {
		t.Fatalf("debería reasignar automáticamente, note=%q", note)
	}
	if !strings.HasPrefix(note, "blocked_task_reassigned:") {
		t.Fatalf("nota inesperada: %q", note)
	}

	actual, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea final: %v", err)
	}
	if actual == nil || actual.Agente == nil || *actual.Agente != "Codex2" || actual.Estado != db.TareaEnProgreso {
		t.Fatalf("tarea inesperada tras reasignación: %+v", actual)
	}
	if !strings.Contains(actual.Notas, "Reasignada automáticamente desde Codex1 a Codex2: bloqueo detectado por transcript") {
		t.Fatalf("nota de reasignación inesperada: %+v", actual)
	}

	agente := "Codex2"
	estado := "pendiente"
	orders, err := db.ListarRuntimeOrders(db.FiltroRuntimeOrders{Agente: &agente, ProyectoID: &proyectoID, Estado: &estado})
	if err != nil {
		t.Fatalf("listar runtime orders: %v", err)
	}
	var continuation *db.RuntimeOrder
	for _, order := range orders {
		if order != nil && order.Tipo == "nudge" && strings.Contains(order.PayloadJSON, `"accion":"continuar_trabajo"`) {
			continuation = order
			break
		}
	}
	if continuation == nil {
		t.Fatalf("faltaba nudge de continuación al relevo: %+v", orders)
	}
	if !strings.Contains(continuation.PayloadJSON, `"reasignada_desde":"Codex1"`) {
		t.Fatalf("payload del relevo inesperado: %s", continuation.PayloadJSON)
	}
}

func TestIntentarReasignacionAutomaticaBlockedSignalTranscriptConRowsUsaHandoffSiOrigenSigueVivo(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)

	if err := db.RegistrarAgente("Codex1", "programador"); err != nil {
		t.Fatalf("registrar agente origen: %v", err)
	}
	if err := db.RegistrarAgente("Codex2", "programador"); err != nil {
		t.Fatalf("registrar agente relevo: %v", err)
	}
	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador",
		Nombre:  "Orquestador",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	proyecto, err := db.GetProyecto(strconv.FormatInt(proyectoID, 10))
	if err != nil {
		t.Fatalf("get proyecto: %v", err)
	}
	for _, agente := range []string{"Codex1", "Codex2"} {
		if err := db.ActivarAsignacion(agente, proyectoID, "frente"); err != nil {
			t.Fatalf("activar asignacion %s: %v", agente, err)
		}
	}
	now := time.Now().UTC()
	writeWorkerMeta := func(dir string) string {
		t.Helper()
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatalf("mkdir trace dir: %v", err)
		}
		statusPath := filepath.Join(dir, "status.json")
		heartbeatPath := filepath.Join(dir, "heartbeat.json")
		if err := os.WriteFile(statusPath, []byte(`{"state":"running","alive":true,"updated_at":"`+now.Format(time.RFC3339Nano)+`"}`), 0o644); err != nil {
			t.Fatalf("write status: %v", err)
		}
		if err := os.WriteFile(heartbeatPath, []byte(`{"alive":true,"heartbeat_at":"`+now.Format(time.RFC3339Nano)+`"}`), 0o644); err != nil {
			t.Fatalf("write heartbeat: %v", err)
		}
		metaJSON, err := json.Marshal(map[string]any{
			"worker_status_path":    statusPath,
			"worker_heartbeat_path": heartbeatPath,
		})
		if err != nil {
			t.Fatalf("marshal metadata: %v", err)
		}
		return string(metaJSON)
	}
	for _, item := range []struct {
		agente string
		dir    string
	}{
		{agente: "Codex1", dir: filepath.Join(tmp, "runtime", "codex1")},
		{agente: "Codex2", dir: filepath.Join(tmp, "runtime", "codex2")},
	} {
		sesion, err := db.IniciarSesionContexto(db.SesionInicio{
			Agente:      item.agente,
			ProyectoID:  &proyectoID,
			CWD:         filepath.Join(tmp, "orquestador"),
			Herramienta: "codex-cli",
		})
		if err != nil {
			t.Fatalf("iniciar sesion %s: %v", item.agente, err)
		}
		handle, err := db.GetRuntimeHandleBySesionID(sesion.ID)
		if err != nil || handle == nil {
			t.Fatalf("handle %s: %+v err=%v", item.agente, handle, err)
		}
		runtimeInst, err := db.GetRuntimeBySesionID(sesion.ID)
		if err != nil || runtimeInst == nil {
			t.Fatalf("runtime %s: %+v err=%v", item.agente, runtimeInst, err)
		}
		metaJSON := writeWorkerMeta(item.dir)
		if _, err := db.DB.Exec(`UPDATE runtime_handles SET estado='activo', metadata_json=? WHERE id=?`, metaJSON, handle.ID); err != nil {
			t.Fatalf("activar handle %s: %v", item.agente, err)
		}
		if _, err := db.DB.Exec(`UPDATE runtime_instances SET logical_state='activo', process_state='running', updated_at=CURRENT_TIMESTAMP WHERE id=?`, runtimeInst.ID); err != nil {
			t.Fatalf("activar runtime %s: %v", item.agente, err)
		}
	}

	tareaID, err := db.CrearTarea(&db.Tarea{
		Titulo:     "Frente bloqueado con transcript y origen vivo",
		ProyectoID: &proyectoID,
		Prioridad:  db.PrioridadAlta,
		CreadoPor:  "tester",
	})
	if err != nil {
		t.Fatalf("crear tarea: %v", err)
	}
	if err := db.TomarTarea(tareaID, "Codex1"); err != nil {
		t.Fatalf("tomar tarea: %v", err)
	}
	tarea, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea inicial: %v", err)
	}
	item := &db.RuntimeTranscriptEntry{
		ID:             92,
		ProyectoID:     &proyectoID,
		Agente:         "Codex1",
		Classification: "blocked",
		Text:           "blocked on missing project context",
	}
	rows := []agentesapp.Row{
		{
			Agente:          &db.Agente{Nombre: "Codex2", Rol: "programador"},
			Asignacion:      &db.Asignacion{Agente: "Codex2", ProyectoID: proyectoID, ProyectoSlug: "orquestador", Estado: db.AsignacionActiva},
			EstadoOperativo: "disponible",
			OpenTasks:       0,
		},
	}

	note, reassigned, err := intentarReasignacionAutomaticaBlockedSignalTranscriptConRows(item, proyecto, tarea, rows, openTasksProjectedFromRows(rows))
	if err != nil {
		t.Fatalf("intentarReasignacionAutomaticaBlockedSignalTranscriptConRows con handoff: %v", err)
	}
	if !reassigned {
		t.Fatalf("deberia resolver con handoff, note=%q", note)
	}
	if !strings.HasPrefix(note, "blocked_task_handoff:") {
		t.Fatalf("nota inesperada: %q", note)
	}

	actual, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea final: %v", err)
	}
	if actual == nil || actual.Agente == nil || *actual.Agente != "Codex2" || actual.Estado != db.TareaAsignada {
		t.Fatalf("tarea inesperada tras handoff: %+v", actual)
	}

	agenteDestino := "Codex2"
	orders, err := db.ListarRuntimeOrders(db.FiltroRuntimeOrders{Agente: &agenteDestino, ProyectoID: &proyectoID, Limit: 20})
	if err != nil {
		t.Fatalf("listar runtime orders: %v", err)
	}
	foundHandoff := false
	foundContinuation := false
	for _, order := range orders {
		if order == nil {
			continue
		}
		if order.Tipo == "handoff" && strings.Contains(order.PayloadJSON, `"agente_origen":"Codex1"`) {
			foundHandoff = true
		}
		if order.Tipo == "nudge" && strings.Contains(order.PayloadJSON, `"accion":"continuar_trabajo"`) {
			foundContinuation = true
		}
	}
	if !foundHandoff {
		t.Fatalf("faltaba handoff al relevo: %+v", orders)
	}
	if !foundContinuation {
		t.Fatalf("faltaba nudge de continuación al relevo: %+v", orders)
	}
}

func TestProcesarIntervencionTareasBloqueadasDegradadasBatchUsaHandoffConProyectoLigero(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)
	autonomiaDegradedTaskGate.Reset()

	if err := db.RegistrarAgente("Codex1", "programador"); err != nil {
		t.Fatalf("registrar agente origen: %v", err)
	}
	if err := db.RegistrarAgente("Codex2", "programador"); err != nil {
		t.Fatalf("registrar agente relevo: %v", err)
	}
	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador-degradado-handoff",
		Nombre:  "Orquestador Degradado Handoff",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	for _, agente := range []string{"Codex1", "Codex2"} {
		if err := db.ActivarAsignacion(agente, proyectoID, "frente"); err != nil {
			t.Fatalf("activar asignacion %s: %v", agente, err)
		}
	}
	now := time.Now().UTC()
	writeWorkerMeta := func(dir string) string {
		t.Helper()
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatalf("mkdir trace dir: %v", err)
		}
		statusPath := filepath.Join(dir, "status.json")
		heartbeatPath := filepath.Join(dir, "heartbeat.json")
		if err := os.WriteFile(statusPath, []byte(`{"state":"running","alive":true,"updated_at":"`+now.Format(time.RFC3339Nano)+`"}`), 0o644); err != nil {
			t.Fatalf("write status: %v", err)
		}
		if err := os.WriteFile(heartbeatPath, []byte(`{"alive":true,"heartbeat_at":"`+now.Format(time.RFC3339Nano)+`"}`), 0o644); err != nil {
			t.Fatalf("write heartbeat: %v", err)
		}
		metaJSON, err := json.Marshal(map[string]any{
			"worker_status_path":    statusPath,
			"worker_heartbeat_path": heartbeatPath,
		})
		if err != nil {
			t.Fatalf("marshal metadata: %v", err)
		}
		return string(metaJSON)
	}
	for _, item := range []struct {
		agente string
		dir    string
	}{
		{agente: "Codex1", dir: filepath.Join(tmp, "runtime", "codex1")},
		{agente: "Codex2", dir: filepath.Join(tmp, "runtime", "codex2")},
	} {
		sesion, err := db.IniciarSesionContexto(db.SesionInicio{
			Agente:      item.agente,
			ProyectoID:  &proyectoID,
			CWD:         filepath.Join(tmp, "orquestador"),
			Herramienta: "codex-cli",
		})
		if err != nil {
			t.Fatalf("iniciar sesion %s: %v", item.agente, err)
		}
		handle, err := db.GetRuntimeHandleBySesionID(sesion.ID)
		if err != nil || handle == nil {
			t.Fatalf("handle %s: %+v err=%v", item.agente, handle, err)
		}
		runtimeInst, err := db.GetRuntimeBySesionID(sesion.ID)
		if err != nil || runtimeInst == nil {
			t.Fatalf("runtime %s: %+v err=%v", item.agente, runtimeInst, err)
		}
		metaJSON := writeWorkerMeta(item.dir)
		if _, err := db.DB.Exec(`UPDATE runtime_handles SET estado='activo', metadata_json=? WHERE id=?`, metaJSON, handle.ID); err != nil {
			t.Fatalf("activar handle %s: %v", item.agente, err)
		}
		if _, err := db.DB.Exec(`UPDATE runtime_instances SET logical_state='activo', process_state='running', updated_at=CURRENT_TIMESTAMP WHERE id=?`, runtimeInst.ID); err != nil {
			t.Fatalf("activar runtime %s: %v", item.agente, err)
		}
	}

	tareaID, err := db.CrearTarea(&db.Tarea{
		Titulo:     "Frente bloqueado con agente degradado",
		ProyectoID: &proyectoID,
		Prioridad:  db.PrioridadAlta,
		CreadoPor:  "tester",
	})
	if err != nil {
		t.Fatalf("crear tarea: %v", err)
	}
	if err := db.TomarTarea(tareaID, "Codex1"); err != nil {
		t.Fatalf("tomar tarea: %v", err)
	}
	if err := db.IniciarTarea(tareaID, "Codex1"); err != nil {
		t.Fatalf("iniciar tarea: %v", err)
	}
	bloqueoMotivo := "Agente Codex1 en estado caido: runtime no responde"
	if err := db.BloquearTarea(tareaID, "Codex1", bloqueoMotivo); err != nil {
		t.Fatalf("bloquear tarea: %v", err)
	}

	tarea, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea: %v", err)
	}
	rows := []agentesapp.Row{
		{
			Agente:          &db.Agente{Nombre: "Codex1", Rol: "programador"},
			Asignacion:      &db.Asignacion{Agente: "Codex1", ProyectoID: proyectoID, ProyectoSlug: "orquestador-degradado-handoff", Estado: db.AsignacionActiva},
			EstadoOperativo: "caido",
			BlockedTasks:    1,
		},
		{
			Agente:          &db.Agente{Nombre: "Codex2", Rol: "programador"},
			Asignacion:      &db.Asignacion{Agente: "Codex2", ProyectoID: proyectoID, ProyectoSlug: "orquestador-degradado-handoff", Estado: db.AsignacionActiva},
			EstadoOperativo: "disponible",
			OpenTasks:       0,
		},
	}
	tareasBloqueadas := map[string][]*db.Tarea{
		"Codex1": {tarea},
	}
	bloqueos := map[int64]db.ResumenBloqueo{
		tareaID: {ID: tareaID, Agente: "Codex1", Motivo: bloqueoMotivo},
	}

	procesadas, err := procesarIntervencionTareasBloqueadasDegradadasBatch(rows, tareasBloqueadas, bloqueos, openTasksProjectedFromRows(rows), now)
	if err != nil {
		t.Fatalf("procesarIntervencionTareasBloqueadasDegradadasBatch: %v", err)
	}
	if procesadas != 1 {
		t.Fatalf("deberia resolver con handoff, got=%d", procesadas)
	}

	actual, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea final: %v", err)
	}
	if actual == nil || actual.Agente == nil || *actual.Agente != "Codex2" || actual.Estado != db.TareaAsignada {
		t.Fatalf("tarea inesperada tras handoff degradado: %+v", actual)
	}

	agenteDestino := "Codex2"
	orders, err := db.ListarRuntimeOrders(db.FiltroRuntimeOrders{Agente: &agenteDestino, ProyectoID: &proyectoID, Limit: 20})
	if err != nil {
		t.Fatalf("listar runtime orders: %v", err)
	}
	foundHandoff := false
	for _, order := range orders {
		if order != nil && order.Tipo == "handoff" && strings.Contains(order.PayloadJSON, `"agente_origen":"Codex1"`) {
			foundHandoff = true
			break
		}
	}
	if !foundHandoff {
		t.Fatalf("faltaba handoff vivo en el relevo: %+v", orders)
	}
	kind := "handoff_requested"
	events, err := db.ListarAutonomyEvents(db.FiltroAutonomyEvents{
		Kind:      &kind,
		ProjectID: &proyectoID,
		TaskID:    ptrInt64Cmd(tareaID),
		Limite:    10,
	})
	if err != nil {
		t.Fatalf("listar autonomy events: %v", err)
	}
	if len(events) != 1 || events[0] == nil {
		t.Fatalf("autonomy events inesperados: %+v", events)
	}
	ev := events[0]
	if ev.Source != "control_plane" || !strings.Contains(ev.Reason, "Agente Codex1 en estado caido") {
		t.Fatalf("handoff_requested inesperado: %+v", ev)
	}
	if fmt.Sprint(ev.StateDelta["last_autonomy_action"]) != "handoff_requested" ||
		fmt.Sprint(ev.StateDelta["agente_origen"]) != "Codex1" ||
		fmt.Sprint(ev.StateDelta["agente_destino"]) != "Codex2" ||
		fmt.Sprint(ev.StateDelta["handoff_mode"]) != "live" {
		t.Fatalf("state_delta handoff_requested inesperado: %+v", ev.StateDelta)
	}
}

