func TestRuntimeMailboxCanDeferSupervisedHandleError(t *testing.T) {
	if runtimeMailboxCanDeferSupervisedHandleError(nil) {
		t.Fatal("nil no deberia diferirse")
	}
	if !runtimeMailboxCanDeferSupervisedHandleError(fmt.Errorf("no se pueden purgar handles con runtime orders vivas asociadas: #1(pendiente)")) {
		t.Fatal("el error de purga bloqueada por runtime orders vivas deberia diferirse")
	}
	if runtimeMailboxCanDeferSupervisedHandleError(fmt.Errorf("otro error")) {
		t.Fatal("errores ajenos no deberian diferirse")
	}
}

func TestRuntimeMailboxHandleDeferredBatchError(t *testing.T) {
	if runtimeMailboxHandleDeferredBatchError("interactive", nil) {
		t.Fatal("nil no deberia diferirse")
	}
	if !runtimeMailboxHandleDeferredBatchError("interactive", fmt.Errorf("no se pueden purgar handles con runtime orders vivas asociadas: #1(pendiente)")) {
		t.Fatal("el batch mailbox deberia diferir este error transitorio")
	}
	if runtimeMailboxHandleDeferredBatchError("interactive", fmt.Errorf("otro error")) {
		t.Fatal("errores ajenos no deberian diferirse a nivel batch")
	}
}

func TestProcesarRuntimeMailboxPhasesRespetaBatchBudget(t *testing.T) {
	runtimeMailboxBatchBudgetOverride = 5 * time.Millisecond
	t.Cleanup(func() { runtimeMailboxBatchBudgetOverride = 0 })

	ejecutadas := []string{}
	total, err := procesarRuntimeMailboxPhases([]runtimeMailboxBatchPhase{
		{
			name:       "primera",
			deferStage: "primera",
			fn: func() (int, error) {
				ejecutadas = append(ejecutadas, "primera")
				time.Sleep(10 * time.Millisecond)
				return 1, nil
			},
		},
		{
			name:       "segunda",
			deferStage: "segunda",
			fn: func() (int, error) {
				ejecutadas = append(ejecutadas, "segunda")
				return 1, nil
			},
		},
	}, runtimeMailboxBatchBudget())
	if err != nil {
		t.Fatalf("procesarRuntimeMailboxPhases: %v", err)
	}
	if total != 1 {
		t.Fatalf("total inesperado=%d", total)
	}
	if len(ejecutadas) != 1 || ejecutadas[0] != "primera" {
		t.Fatalf("deberia cortar tras agotar presupuesto, ejecutadas=%v", ejecutadas)
	}
}

