func TestProcesarAgentesDegradadosAutonomiaBatchReasignaSiAgenteBloqueadoPorCuotaTieneRelevoSano(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)
	autonomiaDegradedTaskGate.Reset()

	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador-cuota-con-relevo",
		Nombre:  "Orquestador Cuota con Relevo",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	for _, agente := range []string{"CodexBloqueado", "CodexLibre"} {
		if err := db.RegistrarAgente(agente, "programador"); err != nil {
			t.Fatalf("registrar agente %s: %v", agente, err)
		}
		if err := db.ActivarAsignacion(agente, proyectoID, "frente bounded"); err != nil {
			t.Fatalf("activar asignacion %s: %v", agente, err)
		}
	}
	if _, err := db.DB.Exec(`UPDATE agentes SET estado_cuota='enfriamiento', motivo_pausa='cuota visible agotada', reanimar_at=datetime('now','+2 hours') WHERE nombre='CodexBloqueado'`); err != nil {
		t.Fatalf("marcar cuota agotada: %v", err)
	}
	sesionLibre, err := db.IniciarSesionContexto(db.SesionInicio{
		Agente:      "CodexLibre",
		ProyectoID:  &proyectoID,
		CWD:         filepath.Join(tmp, "orquestador"),
		Herramienta: "codex-cli",
	})
	if err != nil {
		t.Fatalf("iniciar sesion relevo: %v", err)
	}
	if err := db.UpsertRuntimeHandleDesdeSesion(sesionLibre); err != nil {
		t.Fatalf("upsert handle relevo: %v", err)
	}
	tareaID, err := db.CrearTarea(&db.Tarea{
		Titulo:      "Reasignar por cuota con relevo",
		Descripcion: "Frente premium acotado.\nWRITE_SET: cmd/controlplane_support.go\nTests minimos: go test ./cmd -run 'TestProcesarAgentesDegradadosAutonomiaBatchReasignaSiAgenteBloqueadoPorCuotaTieneRelevoSano$'",
		ProyectoID:  &proyectoID,
		Prioridad:   db.PrioridadAlta,
		CreadoPor:   "alberto",
	})
	if err != nil {
		t.Fatalf("crear tarea: %v", err)
	}
	if err := db.TomarTarea(tareaID, "CodexBloqueado"); err != nil {
		t.Fatalf("tomar tarea: %v", err)
	}
	if err := db.IniciarTarea(tareaID, "CodexBloqueado"); err != nil {
		t.Fatalf("iniciar tarea: %v", err)
	}

	procesadas, err := procesarAgentesDegradadosAutonomiaBatch()
	if err != nil {
		t.Fatalf("procesar agentes degradados: %v", err)
	}
	if procesadas != 1 {
		t.Fatalf("deberia reasignar la tarea bloqueada por cuota al relevo sano, got=%d", procesadas)
	}
	tarea, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea: %v", err)
	}
	if tarea.Estado != db.EstadoEnProgreso || tarea.Agente == nil || *tarea.Agente != "CodexLibre" {
		t.Fatalf("la tarea deberia quedar reasignada al relevo sano: %+v", tarea)
	}
	agente := "CodexLibre"
	estado := "pendiente"
	orders, err := db.ListarRuntimeOrders(db.FiltroRuntimeOrders{Agente: &agente, ProyectoID: &proyectoID, Estado: &estado})
	if err != nil {
		t.Fatalf("listar runtime orders relevo: %v", err)
	}
	if len(orders) != 1 || orders[0] == nil || orders[0].Tipo != "nudge" {
		t.Fatalf("deberia encolar continuidad al relevo por cuota: %+v", orders)
	}
	if !strings.Contains(orders[0].PayloadJSON, `"accion":"continuar_trabajo"`) {
		t.Fatalf("payload nudge inesperado: %s", orders[0].PayloadJSON)
	}
}

func TestBloquearTareasActivasPorCuotaAutonomiaUsaHandoffSiHayRelevoSano(t *testing.T) {
	tmp := prepararDBTemporalCmd(t)

	proyectoID, err := db.UpsertProyecto(&db.Proyecto{
		Slug:    "orquestador-cuota-handoff-directo",
		Nombre:  "Orquestador Cuota Handoff Directo",
		RutaAbs: filepath.Join(tmp, "orquestador"),
		Tipo:    db.ProyectoRepo,
		Activo:  true,
	})
	if err != nil {
		t.Fatalf("upsert proyecto: %v", err)
	}
	for _, agente := range []string{"CodexBloqueado", "CodexLibre"} {
		if err := db.RegistrarAgente(agente, "programador"); err != nil {
			t.Fatalf("registrar agente %s: %v", agente, err)
		}
		if err := db.ActivarAsignacion(agente, proyectoID, "frente bounded"); err != nil {
			t.Fatalf("activar asignacion %s: %v", agente, err)
		}
	}
	now := time.Now().UTC()
	writeWorkerMeta := func(dir string) string {
		t.Helper()
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatalf("mkdir trace dir: %v", err)
		}
		statusPath := filepath.Join(dir, "status.json")
		heartbeatPath := filepath.Join(dir, "heartbeat.json")
		if err := os.WriteFile(statusPath, []byte(`{"state":"running","alive":true,"updated_at":"`+now.Format(time.RFC3339Nano)+`"}`), 0o644); err != nil {
			t.Fatalf("write status: %v", err)
		}
		if err := os.WriteFile(heartbeatPath, []byte(`{"alive":true,"heartbeat_at":"`+now.Format(time.RFC3339Nano)+`"}`), 0o644); err != nil {
			t.Fatalf("write heartbeat: %v", err)
		}
		metaJSON, err := json.Marshal(map[string]any{
			"worker_status_path":    statusPath,
			"worker_heartbeat_path": heartbeatPath,
		})
		if err != nil {
			t.Fatalf("marshal metadata: %v", err)
		}
		return string(metaJSON)
	}
	for _, item := range []struct {
		agente string
		dir    string
	}{
		{agente: "CodexBloqueado", dir: filepath.Join(tmp, "runtime", "codex-bloqueado")},
		{agente: "CodexLibre", dir: filepath.Join(tmp, "runtime", "codex-libre")},
	} {
		sesion, err := db.IniciarSesionContexto(db.SesionInicio{
			Agente:      item.agente,
			ProyectoID:  &proyectoID,
			CWD:         filepath.Join(tmp, "orquestador"),
			Herramienta: "codex-cli",
		})
		if err != nil {
			t.Fatalf("iniciar sesion %s: %v", item.agente, err)
		}
		handle, err := db.GetRuntimeHandleBySesionID(sesion.ID)
		if err != nil || handle == nil {
			t.Fatalf("handle %s: %+v err=%v", item.agente, handle, err)
		}
		runtimeInst, err := db.GetRuntimeBySesionID(sesion.ID)
		if err != nil || runtimeInst == nil {
			t.Fatalf("runtime %s: %+v err=%v", item.agente, runtimeInst, err)
		}
		metaJSON := writeWorkerMeta(item.dir)
		if _, err := db.DB.Exec(`UPDATE runtime_handles SET estado='activo', metadata_json=? WHERE id=?`, metaJSON, handle.ID); err != nil {
			t.Fatalf("activar handle %s: %v", item.agente, err)
		}
		if _, err := db.DB.Exec(`UPDATE runtime_instances SET logical_state='activo', process_state='running', updated_at=CURRENT_TIMESTAMP WHERE id=?`, runtimeInst.ID); err != nil {
			t.Fatalf("activar runtime %s: %v", item.agente, err)
		}
	}
	if _, err := db.DB.Exec(`UPDATE agentes SET estado_cuota='enfriamiento', motivo_pausa='cuota visible agotada', reanimar_at=datetime('now','+2 hours') WHERE nombre='CodexBloqueado'`); err != nil {
		t.Fatalf("marcar cuota agotada: %v", err)
	}
	tareaID, err := db.CrearTarea(&db.Tarea{
		Titulo:      "Relevar por cuota con handoff directo",
		Descripcion: "test",
		ProyectoID:  &proyectoID,
		Prioridad:   db.PrioridadAlta,
		CreadoPor:   "alberto",
	})
	if err != nil {
		t.Fatalf("crear tarea: %v", err)
	}
	if err := db.TomarTarea(tareaID, "CodexBloqueado"); err != nil {
		t.Fatalf("tomar tarea: %v", err)
	}
	if err := db.IniciarTarea(tareaID, "CodexBloqueado"); err != nil {
		t.Fatalf("iniciar tarea: %v", err)
	}

	if err := bloquearTareasActivasPorCuotaAutonomia("CodexBloqueado", "cuota visible agotada"); err != nil {
		t.Fatalf("bloquearTareasActivasPorCuotaAutonomia: %v", err)
	}

	tarea, err := db.GetTarea(tareaID)
	if err != nil {
		t.Fatalf("get tarea: %v", err)
	}
	if tarea.Estado != db.EstadoAsignada || tarea.Agente == nil || *tarea.Agente != "CodexLibre" {
		t.Fatalf("la tarea deberia quedar relevada por handoff: %+v", tarea)
	}
	agente := "CodexLibre"
	orders, err := db.ListarRuntimeOrders(db.FiltroRuntimeOrders{Agente: &agente, ProyectoID: &proyectoID, Limit: 20})
	if err != nil {
		t.Fatalf("listar runtime orders relevo: %v", err)
	}
	foundHandoff := false
	foundContinuation := false
	for _, order := range orders {
		if order == nil {
			continue
		}
		if order.Tipo == "handoff" && strings.Contains(order.PayloadJSON, `"agente_origen":"CodexBloqueado"`) {
			foundHandoff = true
		}
		if order.Tipo == "nudge" && strings.Contains(order.PayloadJSON, `"accion":"continuar_trabajo"`) {
			foundContinuation = true
		}
	}
	if !foundHandoff {
		t.Fatalf("faltaba handoff al relevo: %+v", orders)
	}
	if !foundContinuation {
		t.Fatalf("faltaba nudge de continuación al relevo: %+v", orders)
	}
}

